// Normaliza el input: acepta {message}, {text}, {query} o body plano
const body = $input.first().json.body || $input.first().json;
const message = body.message || body.text || body.query || body.pregunta || '';
const session_id = body.session_id || body.user_id || 'default';
if (!message) throw new Error('Falta el campo message/text/query en el body');
return [{ json: { message, session_id } }];

// Sub-workflow de calcular_costo_estimado
// Inputs: service_type_id, measurement_type, contractor_name, network_operator_group
const body = $input.first().json.body || $input.first().json;
const service_type_id = body.service_type_id || 'INST';
const measurement_type = (body.measurement_type || 'Directa').toLowerCase();
const contractor_name = body.contractor_name || null;
const or_group = body.network_operator_group || 'ENEL_AIRE_EMCALI_AFINIA';

// Mapear tipo de medida → columna de horas
const hoursCol = measurement_type.includes('semi') ? 'semidirect_hours'
               : measurement_type.includes('ind')  ? 'indirect_hours'
               : 'direct_hours';

const sql = `
SELECT
  ot.operation_type,
  ot.${hoursCol} AS hours_required,
  tc.contractor_id,
  c.contractor_name,
  tc.activity_name,
  tc.base_rate_cop,
  tc.network_operator_group,
  ROUND(tc.base_rate_cop * ot.${hoursCol}) AS estimated_cost_cop
FROM operation_types ot
CROSS JOIN tariff_catalog tc
JOIN contractors c ON c.id = tc.contractor_id
WHERE ot.service_type_id = '${service_type_id}'
  AND tc.network_operator_group = '${or_group}'
  ${contractor_name ? `AND c.contractor_name ILIKE '%${contractor_name.replace(/'/g, "''")}%'` : ''}
  AND ot.${hoursCol} IS NOT NULL
ORDER BY estimated_cost_cop
LIMIT 20
`;

return [{ json: { sql: sql.trim() } }];
